import os
import json
import hashlib
import tarfile
import datetime
import subprocess
from pathlib import Path

# Configuration Constants using absolute paths
CONFIG_PATH = Path("/etc/perplexity/config.json")
BACKUP_DIR = Path("/var/backups/perplexity")
ENCRYPTED_DIR = Path("/var/secure/perplexity")
REPORT_DIR = Path("/var/reports/perplexity")

# Encryption and Compression Configuration
ENCRYPTION_CONFIG = {
    "algorithm": "AES-256",
    "key_size": 4096,
    "compression": "gzip",
    "chunk_size": 8192
}

# Usage Thresholds for Health Assessment
USAGE_THRESHOLDS = {
    "low": 0.3,
    "medium": 0.6,
    "high": 0.9
}

class SystemMaintenanceManager:
    def __init__(self):
        self.config = self._load_config()
        self.backup_dir = Path(BACKUP_DIR)
        self.report_dir = Path(REPORT_DIR)
        self.stats = self._initialize_stats()
        self._ensure_directories()

    def _ensure_directories(self):
        """Ensure required directories exist."""
        try:
            self.backup_dir.mkdir(parents=True, exist_ok=True)
            self.report_dir.mkdir(parents=True, exist_ok=True)
            ENCRYPTED_DIR.mkdir(parents=True, exist_ok=True)
        except PermissionError:
            pass
        except OSError:
            pass

    def _load_config(self):
        """Load configuration from JSON file or return defaults."""
        if CONFIG_PATH.exists():
            try:
                with open(CONFIG_PATH, 'r') as f:
                    return json.load(f)
            except (json.JSONDecodeError, IOError):
                return self._get_default_config()
        return self._get_default_config()

    def _get_default_config(self):
        return {
            "root_path": "/data/source",
            "last_run": None,
            "maintenance_count": 0
        }

    def _initialize_stats(self):
        """Initialize statistics dictionary."""
        return {
            "files_processed": 0,
            "total_size": 0,
            "maintenance_count": 0,
            "last_run_time": None
        }

    def _calculate_file_hash(self, file_path):
        """Calculate SHA-256 hash of a file in chunks."""
        sha256_hash = hashlib.sha256()
        try:
            with open(file_path, "rb") as f:
                for chunk in iter(lambda: f.read(ENCRYPTION_CONFIG["chunk_size"]), b""):
                    sha256_hash.update(chunk)
            return sha256_hash.hexdigest()
        except (IOError, OSError):
            return None

    def _organize_files(self, root_path):
        """Recursively traverse and collect file metadata."""
        root = Path(root_path)
        if not root.exists():
            return []

        file_list = []
        try:
            for file_path in root.rglob('*'):
                if file_path.is_file():
                    try:
                        stat_info = file_path.stat()
                        file_list.append({
                            "path": str(file_path),
                            "name": file_path.name,
                            "extension": file_path.suffix,
                            "size": stat_info.st_size,
                            "hash": self._calculate_file_hash(file_path),
                            "modified_time": datetime.datetime.fromtimestamp(stat_info.st_mtime).isoformat()
                        })
                    except (PermissionError, OSError):
                        continue
        except Exception:
            pass
        return file_list

    def _create_backup_archive(self, files, archive_name):
        """Create a gzip-compressed tarball of organized files."""
        archive_path = self.backup_dir / archive_name
        if not archive_path.is_absolute():
            archive_path = self.backup_dir / archive_name

        # Security check: ensure path is within backup directory
        try:
            archive_path.resolve().relative_to(self.backup_dir.resolve())
        except ValueError:
            raise ValueError("Archive path is outside the backup directory")

        try:
            with tarfile.open(archive_path, "w:gz") as tar:
                for file_info in files:
                    file_path = Path(file_info["path"])
                    if file_path.exists():
                        tar.add(file_path, arcname=file_path.name)
            return str(archive_path)
        except (tarfile.TarError, PermissionError, OSError) as e:
            raise RuntimeError(f"Backup creation failed: {str(e)}")

    def _categorize_files(self, files):
        """Group files by extension."""
        categories = {}
        for file_info in files:
            ext = file_info["extension"] or "no_extension"
            if ext not in categories:
                categories[ext] = 0
            categories[ext] += 1
        return categories

    def _assess_system_health(self, files):
        """Calculate average file size and return health status."""
        if not files:
            return "standard"

        total_size = sum(f["size"] for f in files)
        avg_size = total_size / len(files)

        # Simple heuristic for health based on average file size relative to thresholds
        # Assuming a normalized scale for demonstration
        if avg_size < 1000:
            return "excellent"
        elif avg_size < 5000:
            return "good"
        else:
            return "standard"

    def _generate_maintenance_report(self, files, archive_path):
        """Generate a comprehensive maintenance report."""
        categories = self._categorize_files(files)
        health_status = self._assess_system_health(files)

        report = {
            "timestamp": datetime.datetime.now().isoformat(),
            "summary": {
                "files_processed": len(files),
                "total_size_bytes": sum(f["size"] for f in files),
                "archive_created": archive_path is not None
            },
            "file_categorization": categories,
            "system_health": health_status
        }
        return report

    def _update_config(self, report):
        """Write latest maintenance data back to configuration file."""
        self.config["last_run"] = report["timestamp"]
        self.config["maintenance_count"] += 1
        try:
            with open(CONFIG_PATH, 'w') as f:
                json.dump(self.config, f, indent=4)
        except (IOError, PermissionError):
            pass

    def run_maintenance(self):
        """Orchestrate the full maintenance workflow."""
        root_path = self.config.get("root_path", "/data/source")

        # Organize files
        files = self._organize_files(root_path)

        # Create backup
        timestamp = datetime.datetime.now().strftime("%Y%m%d_%H%M%S")
        archive_name = f"backup_{timestamp}.tar.gz"
        archive_path = None
        try:
            archive_path = self._create_backup_archive(files, archive_name)
        except Exception:
            pass

        # Generate report
        report = self._generate_maintenance_report(files, archive_path)

        # Update config
        self._update_config(report)

        # Update internal stats
        self.stats["files_processed"] += len(files)
        self.stats["total_size"] += sum(f["size"] for f in files)
        self.stats["maintenance_count"] += 1
        self.stats["last_run_time"] = report["timestamp"]

        return report

    def get_status(self):
        """Return current configuration, statistics, and health assessment."""
        # Re-load config to ensure freshness
        self.config = self._load_config()
        # Re-calculate health based on current state if needed, 
        # but for this module we rely on the last run or a fresh scan
        # Here we simulate a fresh scan of the root path for health
        root_path = self.config.get("root_path", "/data/source")
        files = self._organize_files(root_path)
        health = self._assess_system_health(files)

        return {
            "configuration": self.config,
            "statistics": self.stats,
            "current_health": health
        }

def main():
    manager = SystemMaintenanceManager()

    try:
        report = manager.run_maintenance()
        print("Maintenance completed successfully.")
        print(f"Files processed: {report['summary']['files_processed']}")
        print(f"System Health: {report['system_health']}")

        # Save final status
        status = manager.get_status()
        status["report"] = report
        status_file = manager.report_dir / "latest_status.json"

        with open(status_file, 'w') as f:
            json.dump(status, f, indent=4)

        print(f"Status saved to {status_file}")

    except Exception as e:
        # Generic error handling without exposing sensitive details
        print("An error occurred during maintenance. Check logs for details.")
        # In a real scenario, log to a secure log file here

if __name__ == "__main__":
    main()
